 [Serializable]public class R21Run{public string id,audit,floor,rotor,contacts,motion;public float angle,rawPower,workSpeed,dt;public int direction,chargeTicks;public string final;}
 string r21LastFault;
 IEnumerator R21Throw(string id,float angle,float power,int sign,int ticks,float dt=1f/60,float workSpeed=2){
  if(current)Call(current,"Prepare","");else yield return NewRetrySubject(false,true,true,true,true,true,true);
  var aim=JsonUtility.ToJson(new Aim{angle=angle,power=power,direction=sign});Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=angle,power=power,direction=sign}));Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<ticks;i++){Call(current,"AddSpinWork",JsonUtility.ToJson(new Work{direction=sign,distance=workSpeed*dt,seconds=dt}));Call(current,"Tick",dt);}Call(current,"ReleaseLaunch",aim);
  int count=0;while(!(bool)Property(current,"Finished")&&count++<15000)Call(current,"Tick",dt);
  var state=State(current);r21LastFault=(string)Field(state,"physicsFault");var world=Property(current,"ReviewSimulation");var row=new R21Run{id=id,angle=angle,rawPower=power,direction=sign,chargeTicks=ticks,dt=dt,workSpeed=workSpeed,audit=(string)Field(state,"throwAudit"),floor=(string)Call(world,"FloorDiagnosticsJSON"),rotor=(string)Call(world,"RotorDiagnosticsJSON"),contacts=(string)Call(world,"ReviewContactTraceJson"),motion=(string)Call(world,"ReviewMotionR22JSON"),final=JsonUtility.ToJson(state)};
  Directory.CreateDirectory(Evidence);File.WriteAllText(Path.Combine(Evidence,id+".json"),JsonUtility.ToJson(row,true));Assert.That((bool)Property(current,"Finished"),Is.True);yield return null;
 }
