 [UnityTest]public IEnumerator R22Causality(){yield return R21Throw("weak70-left607",70,55,-1,607);yield return R21Throw("strong70-left607",70,100,-1,607);yield return R21Throw("weak16-right601",16,55,1,601);yield return R21Throw("weak12-right607",12,55,1,607);yield return R21Throw("weak28-left601",28,55,-1,601);Call(current,"ShutdownReviewPhysics");current=null;}
