 [UnityTest,Timeout(900000)]public IEnumerator R21Acceptance40(){int n=0;var faults=new List<string>();foreach(int ticks in new[]{601,607})foreach(int sign in new[]{1,-1})foreach(float angle in new[]{12f,16f,28f,45f,70f})foreach(float power in new[]{55f,100f}){n++;yield return R21Throw(n.ToString("D2")+"-a"+angle+"-p"+power+"-s"+sign+"-t"+ticks,angle,power,sign,ticks);if(r21LastFault.Length>0)faults.Add(n+":"+r21LastFault);}
  Assert.That(n,Is.EqualTo(40));Assert.That(faults,Is.Empty,string.Join(",",faults));Call(current,"ShutdownReviewPhysics");current=null;}
 [Serializable]public class R21Mesh {public string name,path;public Vector3[] points;public int[] triangles;}
 [Serializable]public class R21Target {public string id,asset,family;public Vector3 position;}
 [Serializable]public class R21Meshes {public List<string> unreadableMeshes=new List<string>();public List<R21Mesh> meshes=new List<R21Mesh>();public List<R21Target> targets=new List<R21Target>();}
 bool ReadSnapshotMeshR21(Mesh mesh,out Vector3[] vertices,out int[] triangles){using(var snapshot=UnityEditor.MeshUtility.AcquireReadOnlyMeshData(mesh)){var data=snapshot[0];if(data.vertexCount==0||!data.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.Position)){vertices=new Vector3[0];triangles=new int[0];return false;}using(var positions=new Unity.Collections.NativeArray<Vector3>(data.vertexCount,Unity.Collections.Allocator.Temp)){data.GetVertices(positions);vertices=positions.ToArray();}var all=new List<int>();for(int s=0;s<data.subMeshCount;s++){using(var indices=new Unity.Collections.NativeArray<int>(data.GetSubMesh(s).indexCount,Unity.Collections.Allocator.Temp)){data.GetIndices(indices,s);all.AddRange(indices.ToArray());}}triangles=all.ToArray();return true;}}
 void SnapshotWorldR21(object sim){var output=new R21Meshes();foreach(var scene in new[]{current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene")})foreach(var root in scene.GetRootGameObjects())foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){var rr=mf.GetComponent<MeshRenderer>();if(!rr||!rr.enabled||!mf.sharedMesh||!mf.gameObject.activeInHierarchy)continue;var names=new List<string>();for(var parent=mf.transform;parent;parent=parent.parent)names.Insert(0,parent.name);string path=string.Join("/",names);if(path.Contains("FlightCrab")||path.Contains("Crab shadow")||path.Contains("landing")||path.Contains("best"))continue;if(!ReadSnapshotMeshR21(mf.sharedMesh,out var vertices,out var triangleIndices)){if(mf.sharedMesh.vertexCount>0)output.unreadableMeshes.Add(path);continue;}for(int i=0;i<vertices.Length;i++)vertices[i]=mf.transform.TransformPoint(vertices[i]);output.meshes.Add(new R21Mesh{name=mf.name,path=path,points=vertices,triangles=triangleIndices});}foreach(var scene in new[]{current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene")})foreach(var root in scene.GetRootGameObjects())foreach(var component in root.GetComponentsInChildren<MonoBehaviour>()){if(component.GetType().FullName!="CrabCityDensityR2.CityVisualBreakable"||!component.gameObject.activeInHierarchy)continue;var points=new List<Vector3>();foreach(var filter in component.GetComponentsInChildren<MeshFilter>()){var rr=filter.GetComponent<MeshRenderer>();if(!rr||!rr.enabled)continue;if(!ReadSnapshotMeshR21(filter.sharedMesh,out var visibleVertices,out var unusedIndices)){if(filter.sharedMesh.vertexCount>0)output.unreadableMeshes.Add("target:"+(string)Field(component,"placementId")+":"+filter.name);continue;}foreach(var v in visibleVertices)points.Add(component.transform.InverseTransformPoint(filter.transform.TransformPoint(v)));}if(points.Count==0)continue;Vector3 lo=points[0],hi=lo;foreach(var v in points){lo=Vector3.Min(lo,v);hi=Vector3.Max(hi,v);}float scale=Mathf.Max((hi-lo).x,(hi-lo).y,(hi-lo).z);var tokens=new SortedSet<string>(StringComparer.Ordinal);foreach(var v in points){var n=(v-lo)/scale;tokens.Add(n.x.ToString("F4",System.Globalization.CultureInfo.InvariantCulture)+","+n.y.ToString("F4",System.Globalization.CultureInfo.InvariantCulture)+","+n.z.ToString("F4",System.Globalization.CultureInfo.InvariantCulture));}output.targets.Add(new R21Target{id=(string)Field(component,"placementId"),asset=(string)Field(component,"assetId"),family=SHA(string.Join(";",tokens)),position=component.transform.position});}File.WriteAllText(Path.Combine(Evidence,"world-mesh-snapshot.json"),JsonUtility.ToJson(output));}
 [Serializable]public class R21Photo {public string section,file,sha256,sourceIdentity;public int width,height;public Vector3 cameraPosition;public Quaternion cameraRotation;public float orthoSize;public bool staticFixture=true;}
