 [UnityTest]public IEnumerator R21InspectAllSections(){yield return NewRetrySubject(false,true,true,true,true,true,true);var recipe=JsonUtility.FromJson<R11RecipeRead>(Resources.Load<TextAsset>("WorldRouteR11").text);var catalog=new R21Photos{sourceIdentity=Resources.Load<TextAsset>("SourceIdentityR21").text};Directory.CreateDirectory(Evidence);var sim=Property(current,"world");SnapshotWorldR21(sim);using(var isolation=new RenderIsolation(current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene"))){var c=(Camera)Property(current,"ReviewCamera");foreach(var sector in recipe.sectors)foreach(var wh in new[]{new[]{390,844},new[]{844,390}}){float size=Mathf.Max(sector.viewSize,wh[0]==390?18:12);c.transform.SetPositionAndRotation(new Vector3(sector.viewX,sector.viewY+10.6f,-32),Quaternion.LookRotation(new Vector3(0,-5.3f,16)));c.orthographicSize=size;c.aspect=(float)wh[0]/wh[1];var rt=new RenderTexture(wh[0],wh[1],24);rt.Create();c.targetTexture=rt;var previous=RenderTexture.active;RenderTexture.active=rt;c.Render();var image=new Texture2D(wh[0],wh[1],TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,wh[0],wh[1]),0,0);image.Apply();var bytes=image.EncodeToPNG();string file=sector.id+"-"+wh[0]+".png";File.WriteAllBytes(Path.Combine(Evidence,file),bytes);string hash;using(var h=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();catalog.photos.Add(new R21Photo{section=sector.id,file=file,sha256=hash,sourceIdentity=catalog.sourceIdentity,width=wh[0],height=wh[1],cameraPosition=c.transform.position,cameraRotation=c.transform.rotation,orthoSize=size});c.targetTexture=null;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 File.WriteAllText(Path.Combine(Evidence,"photo-manifest.json"),JsonUtility.ToJson(catalog,true));Call(current,"ShutdownReviewPhysics");current=null;yield return null;}

 [Serializable]public class R21Fit {public bool newFit;public int pose;public float visualSupport,physicalSupport,supportGap,maxVertexOutside,p95VertexOutside;public int colliderCount,vertices;}
 [Serializable]public class R21FitReport {public string method="identical visible Hero2 charged pose; old13primitives/new13visible-part convex hulls only;6orientation fixtures,not acceptance throws";public List<R21Fit> rows=new List<R21Fit>();}
 [UnityTest]public IEnumerator R21ColliderFit(){var report=new R21FitReport();Directory.CreateDirectory(Evidence);foreach(bool fit in new[]{false,true}){yield return NewRetrySubject(false,true,true,true,true,true,true);var world=Property(current,"world");world.GetType().GetField("UseHeroColliderFitR21").SetValue(world,fit);Call(current,"Rebuild");yield return null;StartRetryCharge();var sim=Property(current,"ReviewSimulation");var body=(Rigidbody)Property(sim,"Body");var root=(Transform)Field(Property(current,"ReviewCrab"),"Root");var shapes=new List<Collider>();foreach(var o in (IEnumerable)Field(sim,"colliders"))shapes.Add((Collider)o);var orientations=new[]{Quaternion.Euler(0,90,0),Quaternion.Euler(180,90,0),Quaternion.Euler(90,90,0),Quaternion.Euler(-90,90,0),Quaternion.Euler(0,90,45),Quaternion.Euler(0,90,-45)};for(int pose=0;pose<orientations.Length;pose++){body.position=Vector3.up*8;body.rotation=orientations[pose];root.SetPositionAndRotation(body.position,body.rotation);UnityEngine.Physics.SyncTransforms();float visual=float.PositiveInfinity,physical=float.PositiveInfinity;var outside=new List<float>();foreach(var shape in shapes)physical=Mathf.Min(physical,((Vector3)Call(sim,"GeometricSupportPointR11",shape)).y);foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){var rr=mf.GetComponent<MeshRenderer>();if(!rr||!rr.enabled)continue;foreach(var v in mf.sharedMesh.vertices){var point=mf.transform.TransformPoint(v);visual=Mathf.Min(visual,point.y);float distance=float.PositiveInfinity;foreach(var shape in shapes)distance=Mathf.Min(distance,(shape.ClosestPoint(point)-point).magnitude);outside.Add(distance);}}outside.Sort();report.rows.Add(new R21Fit{newFit=fit,pose=pose,visualSupport=visual,physicalSupport=physical,supportGap=physical-visual,maxVertexOutside=outside[outside.Count-1],p95VertexOutside=outside[(int)(outside.Count*.95f)],colliderCount=shapes.Count,vertices=outside.Count});}File.WriteAllText(Path.Combine(Evidence,"collider-fit.json"),JsonUtility.ToJson(report,true));Call(current,"Prepare","");Call(current,"ShutdownReviewPhysics");current=null;yield return null;}Assert.That(report.rows.Count,Is.EqualTo(12));}

